  cards.forEach(card => {
    const titleEl = card.querySelector('a.titlestring, .posting-title, .title, a[class*="posting"]');
    const priceEl = card.querySelector('.priceinfo, .price, [class*="price"]');
    const metaEl = card.querySelector('.meta, .post-meta, [class*="meta"]');
    const locationEl = card.querySelector('.location, [class*="location"]');
    const linkEl = card.querySelector('a[href*="/apa/"]');
    if (titleEl || priceEl) {
      results.push({
        title: titleEl?.textContent?.trim() || card.querySelector('a')?.textContent?.trim(),
        price: priceEl?.textContent?.trim(),
        meta: metaEl?.textContent?.trim(),
        location: locationEl?.textContent?.trim(),
        href: linkEl?.href || card.querySelector('a')?.href
      });
    }
  });
  return results;
});

